    [23323]={name="Crown of the Fire Festival",quality=1,ilvl=1,sourceType="quest_reward",instructions="Reward from the quest 'A Thief's Reward'.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
